 }
 private static Map<String,Object> probe(Schema.SObjectType token,Boolean hasField,Map<Id,Schema.RecordTypeInfo> infos,String shape,Id recordTypeId) {
  Map<String,Object> result=new Map<String,Object>{'shape'=>shape};
  SObject row=token.newSObject();row.put('Name','Partial '+shape);
  try{if(shape!='omitted'){row.put('RecordTypeId',recordTypeId);}}catch(Exception e){result.put('assignmentException',new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()});return result;}
  result.put('callerBefore',projection(row,hasField,infos));
  Database.SaveResult saved=Database.insert(row,false);List<Object> errors=new List<Object>();
  for(Database.Error error:saved.getErrors()){errors.add(new Map<String,Object>{'status'=>String.valueOf(error.getStatusCode()),'fields'=>error.getFields(),'message'=>projectMessage(error.getMessage(),infos)});}
  result.put('partial',new Map<String,Object>{'success'=>saved.isSuccess(),'idPresent'=>saved.getId()!=null,'errors'=>errors});
  result.put('callerAfter',projection(row,hasField,infos));
  if(saved.isSuccess()) {Id rowId=saved.getId();SObject persisted=Database.query('SELECT Id,Name'+(hasField?',RecordTypeId':'')+' FROM '+token.getDescribe().getName()+' WHERE Id=:rowId');result.put('persisted',projection(persisted,hasField,infos));}
  SObject throwing=token.newSObject();throwing.put('Name','Throwing '+shape);if(shape!='omitted'){throwing.put('RecordTypeId',recordTypeId);}
  try{insert throwing;result.put('throwing',new Map<String,Object>{'success'=>true,'caller'=>projection(throwing,hasField,infos)});}catch(Exception e){Map<String,Object> details=new Map<String,Object>{'success'=>false,'type'=>e.getTypeName(),'message'=>projectMessage(e.getMessage(),infos)};if(e instanceof DmlException){DmlException de=(DmlException)e;details.put('firstStatus',String.valueOf(de.getDmlStatusCode(0)));List<String> fieldNames=new List<String>();for(Schema.SObjectField field:de.getDmlFields(0)){fieldNames.add(String.valueOf(field));}details.put('firstFields',fieldNames);}result.put('throwing',details);}
  return result;
 }
 private static Map<String,Object> projection(SObject row,Boolean hasField,Map<Id,Schema.RecordTypeInfo> infos) {
  String developerName='field-absent';if(hasField){Id value=(Id)row.get('RecordTypeId');developerName=value==null?'null':(infos.containsKey(value)?infos.get(value).getDeveloperName():'unmapped');}
  return new Map<String,Object>{'idPresent'=>row.Id!=null,'recordType'=>developerName,'populatedRecordType'=>row.getPopulatedFieldsAsMap().containsKey('RecordTypeId'),'jsonRecordType'=>JSON.serialize(row).contains('"RecordTypeId":')};
 }
 private static String projectMessage(String message,Map<Id,Schema.RecordTypeInfo> infos) {
  for(Id key:infos.keySet()){String replacement='<RT:'+infos.get(key).getDeveloperName()+'>';message=message.replace(String.valueOf(key),replacement).replace(String.valueOf(key).substring(0,15),replacement);}return message;
 }
}

